use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "Must read",
        Importance::WorthALook => "Worth a look",
        Importance::Skip => "Skip",
    }
}

fn push_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    let title = e.title.trim();
    if title.is_empty() {
        out.push_str("(untitled)");
    } else {
        out.push_str(title);
    }
    out.push('\n');
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(summary);
        out.push('\n');
    }
    let link = e.link.trim();
    if !link.is_empty() {
        out.push_str("  ");
        out.push_str(link);
        out.push('\n');
    }
    let feed = e.feed.trim();
    if !feed.is_empty() {
        out.push_str("  via ");
        out.push_str(feed);
        out.push('\n');
    }
}

fn render(
    date: &str,
    overview: &str,
    entries: &[ItemVerdict],
    considered: usize,
) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(date);
    out.push('\n');

    let overview = overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    let mut shown: usize = 0;
    for level in [
        Importance::MustRead,
        Importance::WorthALook,
        Importance::Skip,
    ] {
        let mut header_written = false;
        for e in entries.iter().filter(|e| e.kept && e.importance == level) {
            if !header_written {
                out.push('\n');
                out.push_str(importance_label(level));
                out.push_str(":\n");
                header_written = true;
            }
            push_entry(&mut out, e);
            shown += 1;
        }
    }

    if shown == 0 {
        out.push_str("\nNo items made the digest this run.\n");
    }

    out.push('\n');
    out.push_str(&shown.to_string());
    out.push_str(" item(s) in digest, ");
    out.push_str(&considered.to_string());
    out.push_str(" considered.\n");
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(
            &composed.date,
            &composed.overview,
            &composed.entries,
            composed.considered.len(),
        );

        // The notifier's answer is reported as-is: `published` says whether
        // the channel actually accepted the digest.
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
